// Assemble the system + user prompts from the manual-trigger inputs.
// Brand voice and the hard SEO rules live here so they are editable without
// touching any node wiring.

const cfg = $input.first().json;

const topic = (cfg.topic || '').trim();
if (!topic) {
  throw new Error('`topic` is required. Run the workflow with a topic, e.g. "n8n error handling patterns".');
}

const keyword = (cfg.focus_keyword || topic).trim();
const category = (cfg.category || 'Workflow Automation').trim();
const tags = Array.isArray(cfg.tags)
  ? cfg.tags
  : String(cfg.tags || '').split(',').map((t) => t.trim()).filter(Boolean);
const wordTarget = Number(cfg.word_target || 1200);
const attempt = Number(cfg.__attempt || 1);
const previousErrors = Array.isArray(cfg.__previous_errors) ? cfg.__previous_errors : [];

// Services that exist on the site. Only these may be linked, so the model
// cannot invent URLs that 404.
const INTERNAL_LINKS = [
  '/services/n8n-workflow-automation',
  '/services/ai-agent-development',
  '/services/whatsapp-automation',
  '/services/telegram-bot-development',
  '/services/rag-systems',
  '/services/business-process-automation',
];

const system = [
  'You are a senior technical writer for FLOLOGIXAUTOMATIONS, an AI automation agency.',
  '',
  'VOICE',
  '- Plain, direct, practitioner-to-practitioner. No hype, no "in today\'s fast-paced world".',
  '- Concrete over abstract. Every claim gets a specific example, number, or code snippet.',
  '- Write like someone who has actually built the thing and will admit what broke.',
  '- British-ish neutral English. Use "automate", not "leverage" or "unlock".',
  '',
  'HARD REQUIREMENTS',
  '- Start the body with a short paragraph. Do NOT include an H1 — the page renders the title itself.',
  '- Use ## and ### headings only. Never # (that would create a duplicate H1).',
  '- Include at least 2 ## sections and at least one ##, ### or numbered list.',
  '- Include a markdown link using ONLY these internal paths when relevant:',
  ...INTERNAL_LINKS.map((l) => '    ' + l),
  '- Include 3-5 numbered or bulleted practical steps somewhere in the body.',
  '- End the body with a short closing line inviting the reader to talk to the team.',
  '',
  'OUTPUT FORMAT',
  '- Reply with a single JSON object and nothing else. No prose before or after.',
  '- Keys: title, meta_title, excerpt, focus_keyword, content, categories, tags, faqs.',
  '- `faqs` is an array of 3 objects with `q` and `a` keys.',
  '- `categories` and `tags` are arrays of short strings.',
].join('\n');

const user = [
  'Write an article with these parameters:',
  '',
  'Topic: ' + topic,
  'Focus keyword (must appear in title and in the first 150 words): ' + keyword,
  'Category: ' + category,
  'Suggested tags: ' + (tags.length ? tags.join(', ') : '(none given)'),
  'Target length: about ' + wordTarget + ' words',
  '',
  'Constraints:',
  '- title: <= 60 characters, includes the focus keyword, reads well in a SERP.',
  '- meta_title: <= 60 characters, may differ from title.',
  '- excerpt: 140-160 characters, ends with a full stop.',
  '- content: markdown body, ~' + wordTarget + ' words, no H1.',
].join('\n');

const retryBlock = previousErrors.length
  ? [
      '',
      'IMPORTANT — your previous attempt was rejected by automated SEO checks:',
      ...previousErrors.map((e) => '  - ' + e),
      '',
      'Fix every one of those problems in this attempt.',
    ].join('\n')
  : '';

return [{
  json: {
    topic,
    focus_keyword: keyword,
    category,
    tags,
    word_target: wordTarget,
    __attempt: attempt,
    __previous_errors: previousErrors,
    messages: [
      { role: 'system', content: system },
      { role: 'user', content: user + retryBlock },
    ],
  },
}];

// Parse the model's JSON reply and normalise it into the exact payload
// shape that POST /api/blog/webhook expects.

const input = $input.first().json;
const cfg = input.__cfg || {};

let raw = '';
if (Array.isArray(input.choices) && input.choices[0]?.message?.content) {
  raw = input.choices[0].message.content;
} else if (input.content) {
  raw = input.content;
} else if (typeof input.text === 'string') {
  raw = input.text;
}

if (!raw) throw new Error('GPT response contained no content');

// Models occasionally wrap JSON in ```json fences despite json_object mode.
const cleaned = raw.trim().replace(/^```(?:json)?\s*/i, '').replace(/```$/, '').trim();

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (err) {
  throw new Error('GPT did not return valid JSON. Raw reply (first 400 chars): ' + raw.slice(0, 400));
}

function slugify(value) {
  return String(value || '')
    .toLowerCase()
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/['"]/g, '')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 80)
    .replace(/-+$/, '');
}

function asArray(value) {
  if (Array.isArray(value)) return value.map((v) => String(v).trim()).filter(Boolean);
  if (typeof value === 'string') return value.split(',').map((v) => v.trim()).filter(Boolean);
  return [];
}

const title = String(parsed.title || '').trim();
const content = String(parsed.content || '').trim();
const slug = slugify(parsed.slug || title);

// FAQs are objects, so they must NOT go through asArray: String({q:..}) yields
// "[object Object]" and every question is silently lost.
function normalizeFaqs(value) {
  if (!Array.isArray(value)) return [];
  return value
    .filter((f) => f && typeof f === 'object')
    .map((f) => ({ q: String(f.q ?? f.question ?? '').trim(), a: String(f.a ?? f.answer ?? '').trim() }))
    .filter((f) => f.q && f.a);
}

const faqs = normalizeFaqs(parsed.faqs);

const payload = {
  action: 'upsert',
  slug: slug,
  title: title,
  meta_title: String(parsed.meta_title || title).trim(),
  excerpt: String(parsed.excerpt || '').trim(),
  content: content,
  author: cfg.author || 'FLOLOGIXAUTOMATIONS',
  // Never auto-publish. The review gate flips this to true.
  published: false,
  categories: asArray(parsed.categories).length ? asArray(parsed.categories) : [cfg.category].filter(Boolean),
  tags: asArray(parsed.tags).length ? asArray(parsed.tags) : asArray(cfg.tags),
  focus_keyword: String(parsed.focus_keyword || cfg.focus_keyword || '').trim(),
  faqs: faqs,
};

return [{ json: { __cfg: cfg, __attempt: cfg.__attempt || 1, payload: payload } }];

// Hard SEO gate. Anything that fails here never reaches the review email.
// Thresholds mirror src/routes/api.blog.webhook.ts and blog.$slug.tsx so the
// site and the pipeline agree on what "good" means.

const input = $input.first().json;
const p = input.payload;
const cfg = input.__cfg || {};

const MIN_WORDS = Number(cfg.min_words || 800);
const errors = [];
const warnings = [];

const title = p.title || '';
const metaTitle = p.meta_title || title;
const excerpt = p.excerpt || '';
const content = p.content || '';
const keyword = (p.focus_keyword || '').toLowerCase();

// --- title -------------------------------------------------------------
if (title.length === 0) errors.push('title is empty');
if (title.length > 60) errors.push('title is ' + title.length + ' chars, must be <= 60');
if (keyword && !title.toLowerCase().includes(keyword)) {
  errors.push('title does not contain the focus keyword "' + keyword + '"');
}
if (metaTitle.length > 60) errors.push('meta_title is ' + metaTitle.length + ' chars, must be <= 60');

// --- slug --------------------------------------------------------------
if (!/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(p.slug || '')) {
  errors.push('slug "' + p.slug + '" is not lowercase-kebab-case; the webhook will reject it');
}
if ((p.slug || '').length > 80) errors.push('slug is longer than 80 chars');

// --- excerpt / meta description ---------------------------------------
if (excerpt.length < 120) errors.push('excerpt is ' + excerpt.length + ' chars, want 140-160');
if (excerpt.length > 160) errors.push('excerpt is ' + excerpt.length + ' chars, must be <= 160');

// --- body --------------------------------------------------------------
const words = content.split(/\s+/).filter(Boolean).length;
if (words < MIN_WORDS) errors.push('content is ' + words + ' words, want at least ' + MIN_WORDS);

// A leading H1 would duplicate the <h1> the page already renders.
if (/^#\s+/m.test(content.trim().slice(0, 200))) {
  errors.push('content contains an H1 (# heading); the page renders the title itself, so use ## and below');
}

const h2Count = (content.match(/^##\s+/gm) || []).length;
if (h2Count < 2) errors.push('content has ' + h2Count + ' H2 sections, want at least 2');

const hasList = /^\s*([-*+]\s+|\d+\.\s+)/m.test(content);
if (!hasList) warnings.push('content has no bulleted or numbered list');

// Focus keyword must appear early, not just somewhere.
const first150 = content.split(/\s+/).slice(0, 150).join(' ').toLowerCase();
if (keyword && !first150.includes(keyword)) {
  errors.push('focus keyword "' + keyword + '" is missing from the first 150 words');
}

const links = [...content.matchAll(/\]\((\/[^)\s]*)\)/g)].map((m) => m[1]);
// Exact-match allowlist. Prefix matching is deliberately NOT used: "/blog" as a
// prefix would wrongly accept "/blog/does-not-exist", which 404s.
const allowed = [
  '/services/n8n-workflow-automation', '/services/ai-agent-development',
  '/services/whatsapp-automation', '/services/telegram-bot-development',
  '/services/rag-systems', '/services/business-process-automation',
  '/solutions/reduce-operational-costs', '/solutions/improve-customer-response',
  '/solutions/scale-business-without-hiring', '/solutions/automate-invoice-processing',
  '/solutions/improve-google-ranking',
  '/services', '/solutions', '/locations', '/industry', '/blog', '/#contact',
];
const badLinks = [...new Set(links)].filter((h) => {
  if (h.startsWith('#') || h.startsWith('http')) return false;
  return !allowed.includes(h);
});
if (badLinks.length) {
  errors.push('content links to routes that do not exist: ' + badLinks.join(', '));
}
if (links.length === 0) warnings.push('content has no internal links');

// --- structured extras -------------------------------------------------
if (!Array.isArray(p.faqs) || p.faqs.length < 2) {
  errors.push('needs at least 2 FAQs; they render visibly and as FAQPage JSON-LD');
}
if (!Array.isArray(p.categories) || p.categories.length === 0) errors.push('no categories');
if (!Array.isArray(p.tags) || p.tags.length === 0) errors.push('no tags');

// Reading time is computed server-side from word_count, so nothing to check here.

if (errors.length) {
  // Surface the failures to the gate AND to the retry prompt.
  return [{ json: {
    __cfg: Object.assign({}, cfg, {
      __attempt: (input.__attempt || 1),
      __previous_errors: errors,
    }),
    __attempt: input.__attempt || 1,
    __errors: errors,
    __warnings: warnings,
    __words: words,
    payload: p,
    valid: false,
  } }];
}

return [{ json: {
  __cfg: cfg,
  __attempt: input.__attempt || 1,
  __errors: [],
  __warnings: warnings,
  __words: words,
  payload: p,
  valid: true,
} }];

// Second attempt: carry the validation errors forward so the prompt
// builder can tell the model exactly what to fix.

const input = $input.first().json;
const cfg = Object.assign({}, input.__cfg, { __attempt: (input.__attempt || 1) + 1 });

return [{ json: {
  topic: cfg.topic,
  focus_keyword: cfg.focus_keyword,
  category: cfg.category,
  tags: cfg.tags,
  word_target: cfg.word_target,
  model: cfg.model,
  author: cfg.author,
  min_words: cfg.min_words,
  __attempt: cfg.__attempt,
  __previous_errors: input.__errors,
} }];

// Flatten the validated draft into the review message.

const { payload: p, __words: words, __warnings: warnings } = $input.first().json;
const approved = 'https://YOUR-DOMAIN.example/blog/' + p.slug;

const lines = [
  '*New blog draft ready for review*',
  '',
  '*Title:* ' + p.title,
  '*Slug:* ' + p.slug,
  '*Words:* ' + words,
  '*Meta title* (' + p.meta_title.length + ' chars): ' + p.meta_title,
  '*Excerpt* (' + p.excerpt.length + ' chars): ' + p.excerpt,
  '*Categories:* ' + (p.categories || []).join(', '),
  '*Tags:* ' + (p.tags || []).join(', '),
  '*FAQs:* ' + (p.faqs || []).length,
  '',
  '*Draft preview*',
  '```' + String(p.content).slice(0, 1200) + (String(p.content).length > 1200 ? '\n… (truncated)' : '') + '```',
];

if (warnings && warnings.length) {
  lines.push('', '*Warnings (non-blocking)*');
  warnings.forEach((w) => lines.push('• ' + w));
}

lines.push(
  '',
  'Approve? Open this workflow\'s Wait node and POST to its resume webhook with:',
  '```json\n{"approve": true}\n```',
  'or `{"approve": false, "note": "tighten the intro"}` to discard.',
  '',
  'After publishing this will be live at ' + approved,
);

return [{ json: { text: lines.join('\n'), preview_url: approved, payload: p } }];

// Discarded by the reviewer — leave an audit trail rather than silently dropping.

const reason = $input.first().json.note || 'no reason given';

return [{ json: {
  discarded: true,
  reason: reason,
  slug: $('SEO Validate').first().json.payload.slug,
  title: $('SEO Validate').first().json.payload.title,
} }];
